def solve():
    target = 1000
    for a in range(1, target // 3):
        # Derivado de a^2 + b^2 = (target - a - b)^2
        # target^2 - 2*target*(a + b) + 2*a*b = 0
        # b * (target - a) = target^2 / 2 - target * a
        num = target * target // 2 - target * a
        den = target - a
        if num % den == 0:
            b = num // den
            if a < b:
                c = target - a - b
                if b < c:
                    return a * b * c


if __name__ == "__main__":
    print(solve())

